-- query 000
SELECT
  *
FROM (VALUES
  ('value0000',  300, 100, 80, 60),
  ('value0001',  250, 90, 70, 50),
  ('value0002', 220, 85, 65, 45),
  ('value0003', 260, 95, 75, 55)) AS v0000(region, v0001, v0002, v0003, v0004)

