-- query 012
SELECT
  'value0009 value0010' AS category,
  SUM(v0023) AS v0006
FROM v0009
WHERE
  v0010 >= CAST('2026-06-22' AS DATE)
UNION ALL
SELECT
  'value0009 value0011' AS category,
  -1 * SUM(v0024) AS v0006
FROM v0009
WHERE
  v0010 >= CAST('2026-06-22' AS DATE)
UNION ALL
SELECT
  'value0012 value0013' AS category,
  SUM(v0023) - SUM(v0024) AS v0006
FROM v0009
WHERE
  v0010 >= CAST('2026-06-22' AS DATE)

