-- query 110
SELECT
  SUM(
    CASE
      WHEN CAST(v0025 AS DATE) >= CAST(date_trunc('week', CAST(today() AS TIMESTAMP)) AS DATE)
       AND CAST(v0025 AS DATE) <= today()
