    COALESCE(v0155.v0146, 0)
      + COALESCE(v0158.v0151, 0) * (1 - COALESCE(v0159.v0142, 0) / NULLIF(v0159.v0141, 0))
      + COALESCE(v0158.v0152, 0) * (1 - COALESCE(v0159.v0144, 0) / NULLIF(v0159.v0143, 0)) AS v0764
  FROM v0134 AS v0154
