    ON v0155.v0135 = v0154.v0135
  LEFT JOIN v0150 AS v0158
    ON v0158.v0135 = v0154.v0135
  LEFT JOIN v0140 AS v0159
    ON v0159.v0135 = v0154.v0135
), v0765 AS (
