      WHEN v0031 = 'value0073'
      THEN 'value0473'
      WHEN v0031 = 'value0110'
      AND v0629 = 'value0192'
      THEN 'value0206 - value0474 value0204'
      WHEN v0031 = 'value0110'
      AND v0629 = 'value0208'
      THEN 'value0206 - value0209 value0210 value0211'
      WHEN v0031 = 'value0110'
      AND v0629 = 'value0212'
      THEN 'value0206 - value0209 value0475 value0213'
      WHEN v0031 = 'value0110'
