  FROM v1148
  WHERE json_get_str(v1434, 'value0741', 'value0774') = 'value0775'
    AND CAST(json_get_str(v1434, 'value0739', 'value0740') AS TIMESTAMP) >= CAST('2026-04-23T00:00:00' AS TIMESTAMP)
